  public void listCameras() {
    cameraList.removeAllItems();
    camera = new Camera();
    if (!camera.init()) {
      JFAWT.showError("Error", "Camera init failed");
      return;
    }
    String[] devices = camera.listDevices();
    camera.uninit();
    if (devices == null || devices.length == 0) {
      JFAWT.showError("Error", "No camera found");
      return;
    }
    JFLog.log("device count=" + devices.length);
    for (int a = 0; a < devices.length; a++) {
      JFLog.log("device=" + devices[a]);
      cameraList.addItem(devices[a]);
    }
    listModes();
  }

  public void listModes() {
    modeList.removeAllItems();
    int idx = cameraList.getSelectedIndex();
    if (idx == -1) return;
    camera = new Camera();
    if (!camera.init()) {
      JFAWT.showError("Error", "Camera init failed");
      return;
    }
    camera.listDevices();
    String[] modes = camera.listModes(idx);
    camera.uninit();
    if (modes == null) return;
    for(String mode : modes) {
      modeList.addItem(mode);
    }
  }

  public String getCurrentTime() {
    double currentTime = encoderCount;
    currentTime /= fps;
    return String.format("%.3f", currentTime);
  }

  public void setState(boolean state) {
    cameraList.setEnabled(state);
  }
